import type { User } from "../domain/user";
import type { UserDto } from "../api/types";

export const toDto = (u: User): UserDto => ({ id: u.id, name: u.fullName });

export const fromDto = (d: UserDto): User =>
  new User(d.id, d.name, d.is_admin ?? false);   // absent -> default

export const UserSchema = z.object({
  id: z.number().int(),
  full_name: z.string(),
  is_admin: z.boolean().default(false),
}).transform((d) => new User(d.id, d.full_name, d.is_admin));

export const user = UserSchema.parse(payload);   // validated and mapped
